#!/usr/bin/env bash
# Warn when a pull request changes an ETL but not the summary-stats baselines CI cannot rebuild.
#
# A baseline of a credentialed release is regenerated by whoever has the data (see
# docs/etl-baselines.md), so CI can only check that a change to the ETL came with a new baseline. This
# warns rather than fails: not every contributor has the data, and not every change moves the output.
#
# Run from the checkout, with the base commit available (`fetch-depth: 2` on a pull_request merge
# commit). Settings come from the environment, as the composite action passes them:
#
#   BASE_REF            the commit to diff against (default: HEAD^1, the base of a PR merge commit)
#   BASELINES           baseline files, one per line, that changes to the ETL must regenerate
#   WATCH               extended regex of the paths whose changes can move the output (default: ^src/)
#   IGNORE              extended regex of paths among those that cannot (default: \.md$)
#   REGENERATE_COMMAND  the command shown in the job summary for regenerating a baseline
#
# Prints `stale=<baselines not regenerated, space-separated>` to $GITHUB_OUTPUT (if set) and appends a
# note to $GITHUB_STEP_SUMMARY (if set). Exits 0 unless git itself fails.
set -euo pipefail

base=${BASE_REF:-HEAD^1}
watch=${WATCH:-^src/}
ignore=${IGNORE:-\.md$}
baselines=${BASELINES:-tests/regression/full_summary_stats.json}

changed=$(git diff --name-only "$base" HEAD)
etl=$(grep -E -- "$watch" <<<"$changed" | grep -vE -- "$ignore" || true)

stale=()
if [[ -z $etl ]]; then
  echo "No ETL changes."
else
  while IFS= read -r baseline; do
    [[ -z $baseline ]] && continue
    if grep -qxF -- "$baseline" <<<"$changed"; then
      echo "The ETL changed and $baseline was regenerated."
    else
      stale+=("$baseline")
    fi
  done <<<"$baselines"
fi

if [[ -n ${GITHUB_OUTPUT:-} ]]; then
  echo "stale=${stale[*]+${stale[*]}}" >>"$GITHUB_OUTPUT"
fi
for baseline in ${stale[@]+"${stale[@]}"}; do
  echo "::warning title=Summary-stats baseline not regenerated::This pull request changes the ETL but not $baseline. If the change moves the output, regenerate the baseline (see the job summary)."
done
if ((${#stale[@]})) && [[ -n ${GITHUB_STEP_SUMMARY:-} ]]; then
  {
    echo "### Summary-stats baseline not regenerated"
    echo
    echo "These ETL files changed:"
    echo
    # shellcheck disable=SC2016 # the backticks are markdown, not a command substitution
    sed 's/^/- `/; s/$/`/' <<<"$etl"
    echo
    echo "but these baselines did not:"
    echo
    # shellcheck disable=SC2016 # as above
    printf -- '- `%s`\n' ${stale[@]+"${stale[@]}"}
    if [[ -n ${REGENERATE_COMMAND:-} ]]; then
      echo
      echo "If the change moves the output, rebuild with this branch and regenerate:"
      echo
      echo '```bash'
      echo "$REGENERATE_COMMAND"
      echo '```'
    fi
  } >>"$GITHUB_STEP_SUMMARY"
fi
